INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-030', TRUE, '安徽农业大学官网', NULL, '我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次', '校内通知', NULL, '2026-11-03', NULL, NULL, NULL, 0.5, 'medium', '[{"text": "我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次 【 发布日期：2026-11-03 】", "quote": "我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次 【 发布日期：2026-11-03 】"}]'::jsonb, '校内通知：我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次', '[{"text": "我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次 【 发布日期：2026-11-03 】", "quote": "我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次 【 发布日期：2026-11-03 】"}]'::jsonb, '我校在安徽省大型科学仪器开放共享评价考核中获评“优秀”等次 【 发布日期：2026-11-03 】 【 来源：实验室与设备管理处 】 【 点击数： 】 本网讯 近日，省科技厅、财政厅、教育厅联合发布2025年度安徽省大型科学仪器开放共享评价考核结果，我校综合考核指标位居省属高校前列并获得评价考核“优秀”等次。全省共58家单位参评，其中4所高校获得优秀等次。 学校高度重视大型科学仪器开放共享，强化顶层设计，立足长效发展，将大型科学仪器开放共享工作纳入学校发展战略全局，管理制度全面规范，对外开放共享成效明显。截至202', 'http://news.ahau.edu.cn/info/1005/143297.htm', '安徽农业大学官网', 'www', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at